Q: threading in pygame A: <pre><code>from gtts import gTTS
import pygame
import io
import time

class SimplePersianTTS:
    &quot;&quot;&quot;نسخه ساده‌تر برای استفاده در پروژه‌های غیرگرافیکی&quot;&quot;&quot;

    def __init__(self):
        pygame.mixer.init()
        self.is_playing = False

    def speak(self, text, slow=False, save=False, filename=None):
        &quot;&quot;&quot;تبدیل متن به گفتار و پخش آن&quot;&quot;&quot;

        if not text.strip():
            return False

        try:
            # تولید صوت
            tts = gTTS(text=text, lang='fa', slow=slow)
            audio_data = io.BytesIO()
            tts.write_to_fp(audio_data)
            audio_data.seek(0)

            # ذخیره فایل اگر درخواست شده باشد
            if save:
                if not filename:
                    timestamp = time.strftime(&quot;%Y%m%d_%H%M%S&quot;)
                    filename = f&quot;tts_output_{timestamp}.mp3&quot;

                with open(filename, 'wb') as f:
                    f.write(audio_data.getvalue())
                print(f&quot;✅ فایل ذخیره شد: {filename}&quot;)

            # پخش صوت
            audio_data.seek(0)
            pygame.mixer.music.load(audio_data)
            pygame.mixer.music.play()

            self.is_playing = True
            print(&quot;🔊 در حال پخش...&quot;)

            # منتظر پایان پخش
            while pygame.mixer.music.get_busy():
                time.sleep(0.1)

            self.is_playing = False
            print(&quot;✅ پخش به پایان رسید&quot;)
            return True

        except Exception as e:
            print(f&quot;❌ خطا: {e}&quot;)
            return False

    def stop(self):
        &quot;&quot;&quot;توقف پخش&quot;&quot;&quot;
        if self.is_playing:
            pygame.mixer.music.stop()
            self.is_playing = False
            print(&quot;⏹️ پخش متوقف شد&quot;)

    def close(self):
        &quot;&quot;&quot;پاکسازی منابع&quot;&quot;&quot;
        pygame.mixer.quit()


# استفاده سریع
if __name__ == &quot;__main__&quot;:
    tts = SimplePersianTTS()

    # مثال‌های مختلف
    examples = [
        &quot;سلام، چطور می‌توانم به شما کمک کنم؟&quot;,
        &quot;دما امروز ۲۵ درجه سانتی‌گراد است.&quot;,
        &quot;سفارش شما با شماره ۱۲۳۴ ثبت شد.&quot;,
    ]

    for i, text in enumerate(examples, 1):
        print(f&quot;\nمثال {i}: {text}&quot;)
        tts.speak(text, save=True)
        time.sleep(1)

    tts.close()
</code></pre>
